package errs

import "net/http"

// Error codes related to large language model features
var (
	ErrLargeLanguageModelProviderNotEnabled   = NewNormalError(NormalSubcategoryLargeLanguageModel, 0, http.StatusBadRequest, "llm provider is not enabled")
	ErrNoAIRecognitionImage                   = NewNormalError(NormalSubcategoryLargeLanguageModel, 1, http.StatusBadRequest, "no image for AI recognition")
	ErrAIRecognitionImageIsEmpty              = NewNormalError(NormalSubcategoryLargeLanguageModel, 2, http.StatusBadRequest, "image for AI recognition is empty")
	ErrExceedMaxAIRecognitionImageFileSize    = NewNormalError(NormalSubcategoryLargeLanguageModel, 3, http.StatusBadRequest, "exceed the maximum size of image file for AI recognition")
	ErrNoTransactionInformation               = NewNormalError(NormalSubcategoryLargeLanguageModel, 4, http.StatusBadRequest, "no transaction information detected")
	ErrNoAIRecognitionText                    = NewNormalError(NormalSubcategoryLargeLanguageModel, 5, http.StatusBadRequest, "no text for AI recognition")
	ErrAIRecognitionTextIsEmpty               = NewNormalError(NormalSubcategoryLargeLanguageModel, 6, http.StatusBadRequest, "text for AI recognition is empty")
	ErrNoAICodingPrompt                       = NewNormalError(NormalSubcategoryLargeLanguageModel, 7, http.StatusBadRequest, "no prompt for AI coding")
	ErrNoAICodingResult                       = NewNormalError(NormalSubcategoryLargeLanguageModel, 8, http.StatusBadGateway, "no code generated by AI")
	ErrLargeLanguageModelDocumentNotSupported = NewNormalError(NormalSubcategoryLargeLanguageModel, 9, http.StatusBadRequest, "llm provider does not support reading documents")
	ErrAIRecognitionDocumentTypeNotSupported  = NewNormalError(NormalSubcategoryLargeLanguageModel, 10, http.StatusBadRequest, "document type is not supported for AI recognition")
	ErrNoAIRecognitionDocumentText            = NewNormalError(NormalSubcategoryLargeLanguageModel, 11, http.StatusBadRequest, "no text found in document for AI recognition")
	ErrDonutModelDownloading                  = NewNormalError(NormalSubcategoryLargeLanguageModel, 12, http.StatusServiceUnavailable, "the receipt recognition model is being downloaded, try again in a few minutes")
	ErrDonutWorkerUnavailable                 = NewNormalError(NormalSubcategoryLargeLanguageModel, 13, http.StatusServiceUnavailable, "the receipt recognition worker is not available")
)
